# fuel code -> display word
_FUEL = {
    "g": "gasoline", "d": "diesel", "e": "electric", "c": "CNG",
    "l": "LPG", "f": "flexible fuel (FFV)",
}


def _ctx_match(ctx: tuple, vin: str, base: int) -> bool:
    """Does the VIN satisfy this context tuple? ``base`` = first position."""
    for i, allowed in enumerate(ctx):
        if not allowed:
            continue
        if vin[base + i - 1] not in allowed:
            return False
    return True


def _facts_merge(a: tuple, b: tuple) -> tuple:
    """Intersection of two fact tuples: fields must agree or drop."""
    out = []
    for x, y in zip(a, b):
        if x == y:
            out.append(x)
        elif x is None:
            out.append(y)
        elif y is None:
            out.append(x)
        else:
            out.append(None)
    return tuple(out)


def _compose(f: tuple) -> Optional[str]:
    displ, cyl, conf, fuel, turbo, emodel = f
    head = ""
    if displ is not None:
        head = f"{displ:g} L" if (displ == int(displ) or displ >= 10) \
            else f"{displ:.1f} L"
    if conf and cyl:
        head = (head + " " if head else "") + f"{conf}{cyl}"
    elif cyl:
        head = (head + " " if head else "") + f"{cyl}-cyl"
    parts = [head] if head else []
    if fuel:
        parts.append(_FUEL.get(fuel, str(fuel).lower()))
    if turbo:
        parts.append("turbocharged")
    if emodel:
        parts.append(f"({emodel})")
    return ", ".join(parts) or None


def engine_for_vin(vin: str) -> Optional[str]:
    """Engine description for a 17-char VIN, fully offline.

    Returns the composed engine string ("3.5 L V6, gasoline,
    turbocharged (GTDI)") for a supported WMI whose engine-code entry
    matches the model year AND the VIN's positions 4-7 / 10-17 context;
    the raw code note when the WMI is supported but the code or context is
    unknown to the table; and None when the WMI is unsupported (the panel
    shows its placeholder).
    """
    vin = (vin or "").strip().upper()
    if len(vin) != 17:
        return None
    table = _ENGINE_CODES.get(vin[:3])
    if not table:
        return None
    code = vin[7]
    year = model_year(vin)
    pool = table.get(code) or []
    matching = [e for e in pool
                if year is not None and e[0] <= year <= e[1]
                and _ctx_match(e[2], vin, 4) and _ctx_match(e[3], vin, 10)]
    if not matching:
        # single-engine layouts carry their facts under "?"
        pool = table.get("?") or []
        matching = [e for e in pool
                    if year is not None and e[0] <= year <= e[1]
                    and _ctx_match(e[2], vin, 4)
                    and _ctx_match(e[3], vin, 10)]
    if not matching:
        return f'VIN engine code "{code}"'
    facts = matching[0][4]
    for e in matching[1:]:
        facts = _facts_merge(facts, e[4])
    desc = _compose(facts)
    if not desc:
        return f'VIN engine code "{code}"'
    return desc


# Public alias for tests/tools.
ENGINE_CODES = _ENGINE_CODES
